    "difficulty": "Fácil",
    "statement": "Na tradição africana, a palavra falada, além de seu valor \nfundamental, possui um caráter sagrado que se associa à sua \norigem divina e às forças ocultas nela depositadas. A tradição \noral, que não se limita aos contos e lendas nem aos relatos \nmíticos e históricos, é a grande escola da vida, recobrindo \ne englobando todos os seus aspectos. Nela, o espiritual e o \nmaterial não se dissociam. Falando segundo a compreensão \nde cada pessoa, ela se coloca ao alcance de todos.\n\nA tradição oral é, ao mesmo tempo, religião, conhecimento, ciência natural, aprendizado de ofício, história, divertimento e recreação. Baseada na prática e na experiência, ela se \nrelaciona à totalidade do ser humano e, assim, contribui para \ncriar um tipo especial de pessoa e moldar sua alma.\n\n(Nei Lopes e Luiz Antonio Simas. \nFilosofias africanas: uma introdução, 2022. Adaptado.)\n\nDe acordo com o excerto, na tradição africana, a linguagem \nverbal",
