    "statement": "O processo de eletrização por indução é um procedimento \ncapaz de eletrizar um corpo que inicialmente estava neutro — ou seja, o corpo induzido — por intermédio de uma \nsequência de ações com um corpo já eletrizado — isto é, o \ncorpo indutor. Para que esse procedimento seja concretizado, é necessário utilizar um terceiro corpo, muito maior que \nos dois primeiros, capaz de receber ou ceder elétrons. Esse \nterceiro corpo é conhecido como aterramento.\n\nConsidere que A é o corpo indutor, B é o corpo induzido e \nC é o aterramento. Na sequência, estão expressas quatro \nfases do processo de eletrização por indução, apresentadas \nem ordem aleatória.\n\n1 – Afasta-se o corpo B do corpo A;\n\n2 – Encosta-se o corpo C no corpo B;\n\n3 – Aproxima-se o corpo B do corpo A;\n\n4 – Separa-se o corpo C do corpo B.\n\nA ordem das fases que constituem o procedimento de eletrização por indução corresponde à sequência",
