    "statement": "Para responder às questões de 01 a 06, leia o trecho do romance Triste fim de Policarpo Quaresma, de Lima Barreto.\n\nE foi obedecendo a essa ordem de ideias que [Policarpo \nQuaresma] comprou aquele sítio, cujo nome — Sossego — \ncabia tão bem à nova vida que adotara, após a tempestade \nque o sacudira durante quase um ano. [...]\n\nEle foi contente. Como era tão simples viver na nossa terra! Quatro contos de réis por ano, tirados da terra, facilmente, \ndocemente, alegremente! Oh! terra abençoada! Como é que \ntoda a gente queria ser empregado público, apodrecer numa \nbanca, sofrer na sua independência e no seu orgulho? Como \né que se preferia viver em casas apertadas, sem ar, sem luz, \nrespirar um ambiente epidêmico, sustentar-se de maus alimentos, quando se podia tão facilmente obter uma vida feliz, \nfarta, livre, alegre e saudável?\n\nE era agora que ele chegava a essa conclusão, depois de \nter sofrido a miséria da cidade e o emasculamento1 da repartição pública, durante tanto tempo! Chegara tarde, mas não \na ponto de que não pudesse, antes da morte, travar conhecimento com a doce vida campestre e a feracidade2 das terras brasileiras. Então pensou que foram vãos aqueles seus \ndesejos de reformas capitais nas instituições e costumes: o \nque era principal à grandeza da pátria estremecida era uma \nforte base agrícola, um culto pelo seu solo ubérrimo3, para \nalicerçar fortemente todos os outros destinos que ela tinha \nde preencher.\n\n(Triste fim de Policarpo Quaresma, 2011.)\n\n1 \u0007emasculamento: perda da virilidade, perda da força ou do vigor.\n2 \u0007feracidade: fertilidade.\n3 \u0007ubérrimo: extremamente úbere (ou seja, fértil).\n\nO trecho evidencia uma característica central do personagem \nPolicarpo Quaresma, a saber, sua personalidade",
