    "statement": "Fomos, durante muito tempo, embalados com a história \nde que somos a humanidade e nos alienamos desse organismo de que somos parte, a Terra, passando a pensar que \nele é uma coisa e nós, outra: a Terra e a humanidade. Eu não \npercebo que exista algo que não seja natureza. Tudo é natureza. O cosmos é natureza. Tudo em que eu consigo pensar \né natureza. Nós, a humanidade, vamos viver em ambientes \nartificiais produzidos pelas grandes corporações, que são os \ndonos da grana.\n\n(Ailton Krenak. O amanhã não está à venda, 2020.)\n\nNo excerto, escrito pelo líder indígena Ailton Krenak, há uma \nreflexão sobre a",
