    "difficulty": "Difícil",
    "statement": "Em janeiro de 1958, com o preço do petróleo relativamente baixo e a entrada da indústria automobilística no país, \nJuscelino Kubitschek avaliou que o desafio de abrir novas \nrodovias de terra vermelha e asfalto valia a pena: mandou \nchamar o engenheiro agrônomo Bernardo Sayão, funcionário \ndo Ministério da Agricultura, um tocador de obras com espírito de desbravador. Juscelino propôs a Sayão cortar os \ncerrados do Brasil Central, nas palavras do presidente: “arrombar a selva e unir o país de norte a sul”. A rede rodoviária \nBelém-Brasília interligou por estrada de rodagem os estados \nde Goiás, Maranhão e Pará, inseriu a Amazônia no mercado \nbrasileiro e forneceu uma nova alternativa para atenuar desequilíbrios regionais.\n\n(Lilia M. Schwarcz e Heloisa M. Starling.\n\nBrasil: uma biografia, 2018. Adaptado.)\n\nDe acordo com o excerto, a inserção da Amazônia no mercado brasileiro foi viabilizada",
    "images": [],
