    "statement": "Pesquisadores desenvolveram mecanismos que possibilitam aos novos sistemas de inteligência artificial (IA) explicar sua cadeia de processamento passo a passo. De fato, as \nmensagens geradas por esses novos sistemas podem parecer uma linha estruturada de raciocínio lógico, o que parece \nmuito surpreendente. No entanto, essas explicações são falaciosas. Quando os grandes modelos de linguagem, usados \npelas IAs, afirmam “estar pensando” sobre um problema, o \nque fazem é apenas gerar probabilisticamente mais texto \ncom base em valores intermediários de processamento, não \nnecessariamente relatando os processos computacionais \nusados para chegar à resposta. Quando solicitados a explicar seu raciocínio, esses modelos constroem uma narrativa \nplausível e, muitas vezes, sugerem que seguiram uma lógica \nestruturada, quando na verdade fizeram meros cálculos textuais probabilísticos.\n\n(https://g1.globo.com, 23.06.2025. Adaptado.)\n\nO trecho da notícia revela que",
